mapper.sql:
SELECT id, skill_name AS skillName, skill_key AS skillKey, description, prompt_template AS promptTemplate, trigger_type AS triggerType, trigger_rules AS triggerRules, icon, sort_order AS sortOrder, status, created_by AS createdBy, created_at AS createdAt, updated_at AS updatedAt FROM sys_skills WHERE 1=1 AND status = #{status}
AND (skill_name LIKE #{keyword} OR skill_key LIKE #{keyword} OR description LIKE #{keyword})
ORDER BY sort_order ASC, id DESC

mapper.update:
UPDATE sys_skills
skill_name = #{row.skillName}, skill_key = #{row.skillKey}, description = #{row.description}, prompt_template = #{row.promptTemplate}, trigger_type = #{row.triggerType}, trigger_rules = #{row.triggerRules}, icon = #{row.icon}, sort_order = #{row.sortOrder}, status = #{row.status}, updated_at = NOW()
WHERE id = #{id}
